//! 📐️ DWG entity geometry is reconstructed from explicit component and reference tables.
use super::super::*;
use super::{drawing::optional_words,number::Projection,reader::{boolean,byte,full_unsigned,high,low,optional_integer,optional_real,optional_text,optional_unsigned,ordinal,real,signed_word,unsigned,word,Reader},entity_dimension,entity_viewport};
use semio_framework_os_kernel::sqlite_snapshot::artifact::Cell;
use Cell::{Integer as I,Real as R,Text as T,Null as N};

pub(super) fn project(projection:&mut Projection<'_,'_>,id:i64,value:&DwgEntityBody)->Result<(),String>{
    let(kind,common)=match value{DwgEntityBody::Line(v)=>("line",&v.common),DwgEntityBody::Arc(v)=>("arc",&v.common),DwgEntityBody::LwPolyline(v)=>("lwpolyline",&v.common),DwgEntityBody::BlockBegin(v)=>("block_begin",&v.common),DwgEntityBody::BlockEnd(v)=>("block_end",&v.common),DwgEntityBody::Insert(v)=>("insert",&v.common),DwgEntityBody::DimensionLinear(v)=>("dimension_linear",&v.dimension.common),DwgEntityBody::Viewport(v)=>("viewport",&v.common),DwgEntityBody::Point(v)=>("point",&v.common),DwgEntityBody::Circle(v)=>("circle",&v.common),DwgEntityBody::Ellipse(v)=>("ellipse",&v.common),DwgEntityBody::Text(v)=>("text",&v.common),DwgEntityBody::Spline(v)=>("spline",&v.common),DwgEntityBody::Face3d(v)=>("face3d",&v.common),DwgEntityBody::Polyline3d(v)=>("polyline3d",&v.common),DwgEntityBody::PolyfaceMesh(v)=>("polyface_mesh",&v.common),DwgEntityBody::Vertex(v)=>("vertex",&v.common),DwgEntityBody::PolyfaceFace(v)=>("polyface_face",&v.common),DwgEntityBody::SequenceEnd(v)=>("sequence_end",&v.common)};
    projection.insert_key("dwg_entity",id,&[T(kind)])?;project_common(projection,id,common)?;
    match value{
        DwgEntityBody::Line(v)=>{projection.insert_key("dwg_line_entity",id,&[R(v.thickness)])?;coordinates(projection,"dwg_entity_line_start_coordinate",id,&v.start)?;coordinates(projection,"dwg_entity_line_end_coordinate",id,&v.end)?;coordinates(projection,"dwg_entity_extrusion_coordinate",id,&v.extrusion)},
        DwgEntityBody::Arc(v)=>{projection.insert_key("dwg_arc_entity",id,&[R(v.radius),R(v.thickness),R(v.start_angle),R(v.end_angle)])?;coordinates(projection,"dwg_entity_center_coordinate",id,&v.center)?;coordinates(projection,"dwg_entity_extrusion_coordinate",id,&v.extrusion)},
        DwgEntityBody::LwPolyline(v)=>{
            projection.insert_key("dwg_lwpolyline_entity",id,&[I(i64::from(v.closed)),v.constant_width.map(R).unwrap_or(N),R(v.elevation),R(v.thickness)])?;coordinates(projection,"dwg_entity_extrusion_coordinate",id,&v.extrusion)?;
            for(index,value)in v.vertices.iter().enumerate(){let vertex=projection.insert("dwg_lwpolyline_vertex",&[I(id),I(ordinal(index)?),R(value.bulge),value.vertex_id.map(|value|I(i64::from(value))).unwrap_or(N),value.start_width.map(R).unwrap_or(N),value.end_width.map(R).unwrap_or(N)])?;coordinates(projection,"dwg_lwpolyline_vertex_coordinate",vertex,&value.point)?;}
            Ok(())
        },
        DwgEntityBody::BlockBegin(_)=>projection.insert_key("dwg_block_begin_entity",id,&[]),DwgEntityBody::BlockEnd(_)=>projection.insert_key("dwg_block_end_entity",id,&[]),DwgEntityBody::SequenceEnd(_)=>projection.insert_key("dwg_sequence_end_entity",id,&[]),
        DwgEntityBody::Insert(v)=>{let end=optional_words(v.sequence_end_handle);projection.insert_key("dwg_insert_entity",id,&[R(v.rotation),I(high(v.block_header_handle)),I(low(v.block_header_handle)),end[0],end[1]])?;coordinates(projection,"dwg_entity_insert_insertion_coordinate",id,&v.insertion)?;coordinates(projection,"dwg_entity_insert_scale_coordinate",id,&v.scale)?;coordinates(projection,"dwg_entity_extrusion_coordinate",id,&v.extrusion)?;handles(projection,"dwg_insert_attribute_handle",id,&v.attribute_handles)},
        DwgEntityBody::Point(v)=>{projection.insert_key("dwg_point_entity",id,&[R(v.thickness),R(v.x_axis_angle)])?;coordinates(projection,"dwg_entity_point_coordinate",id,&v.point)?;coordinates(projection,"dwg_entity_extrusion_coordinate",id,&v.extrusion)},
        DwgEntityBody::Circle(v)=>{projection.insert_key("dwg_circle_entity",id,&[R(v.radius),R(v.thickness)])?;coordinates(projection,"dwg_entity_center_coordinate",id,&v.center)?;coordinates(projection,"dwg_entity_extrusion_coordinate",id,&v.extrusion)},
        DwgEntityBody::Ellipse(v)=>{projection.insert_key("dwg_ellipse_entity",id,&[R(v.axis_ratio),R(v.start_parameter),R(v.end_parameter)])?;coordinates(projection,"dwg_entity_center_coordinate",id,&v.center)?;coordinates(projection,"dwg_entity_ellipse_major_axis_coordinate",id,&v.major_axis)?;coordinates(projection,"dwg_entity_extrusion_coordinate",id,&v.extrusion)},
        DwgEntityBody::Text(v)=>{
            projection.insert_key("dwg_text_entity",id,&[R(v.elevation),I(i64::from(v.alignment.is_some())),R(v.thickness),R(v.oblique_angle),R(v.rotation),R(v.height),R(v.width_factor),T(&v.value),I(i64::from(v.generation)),I(i64::from(v.horizontal_alignment)),I(i64::from(v.vertical_alignment)),I(high(v.style_handle)),I(low(v.style_handle))])?;
            coordinates(projection,"dwg_entity_text_insertion_coordinate",id,&v.insertion)?;if let Some(alignment)=&v.alignment{coordinates(projection,"dwg_entity_text_alignment_coordinate",id,alignment)?;}coordinates(projection,"dwg_entity_extrusion_coordinate",id,&v.extrusion)
        },
        DwgEntityBody::Spline(v)=>{projection.insert_key("dwg_spline_entity",id,&[I(i64::from(v.degree)),I(i64::from(v.rational)),I(i64::from(v.closed)),I(i64::from(v.periodic)),R(v.knot_tolerance),R(v.control_tolerance)])?;coordinates(projection,"dwg_entity_spline_knot",id,&v.knots)?;coordinates(projection,"dwg_entity_spline_control_coordinate",id,&v.control_points)?;coordinates(projection,"dwg_entity_spline_weight",id,&v.weights)},
        DwgEntityBody::Face3d(v)=>{projection.insert_key("dwg_face3d_entity",id,&[I(i64::from(v.invisible_edges))])?;coordinates(projection,"dwg_entity_face3d_corner_coordinate",id,&v.corners)},
        DwgEntityBody::Polyline3d(v)=>{projection.insert_key("dwg_polyline3d_entity",id,&[I(i64::from(v.curve_type)),I(i64::from(v.flags)),I(high(v.sequence_end_handle)),I(low(v.sequence_end_handle))])?;handles(projection,"dwg_polyline3d_vertex_handle",id,&v.vertex_handles)},
        DwgEntityBody::PolyfaceMesh(v)=>{projection.insert_key("dwg_polyface_mesh_entity",id,&[I(i64::from(v.vertex_count)),I(i64::from(v.face_count)),I(high(v.sequence_end_handle)),I(low(v.sequence_end_handle))])?;handles(projection,"dwg_polyface_mesh_vertex_handle",id,&v.vertex_handles)},
        DwgEntityBody::Vertex(v)=>{projection.insert_key("dwg_vertex_entity",id,&[I(i64::from(v.flags))])?;coordinates(projection,"dwg_entity_vertex_coordinate",id,&v.point)},
        DwgEntityBody::PolyfaceFace(v)=>{projection.insert_key("dwg_polyface_face_entity",id,&[])?;for(index,value)in v.indices.iter().enumerate(){projection.insert("dwg_polyface_face_index",&[I(id),I(ordinal(index)?),I(i64::from(*value))])?;}Ok(())},
        DwgEntityBody::DimensionLinear(v)=>entity_dimension::project(projection,id,v),DwgEntityBody::Viewport(v)=>entity_viewport::project(projection,id,v)
    }
}
pub(super) fn coordinates(projection:&mut Projection<'_,'_>,table:&'static str,id:i64,values:&[f64])->Result<(),String>{for(index,value)in values.iter().enumerate(){projection.insert(table,&[I(id),I(ordinal(index)?),R(*value)])?;}Ok(())}
pub(super) fn read_coordinates(reader:&mut Reader<'_,'_,'_>,table:&'static str,id:i64)->Result<Vec<f64>,String>{reader.list(table,1,id,2)?.into_iter().map(|row|real(row,3)).collect()}
pub(super) fn handles(projection:&mut Projection<'_,'_>,table:&'static str,id:i64,values:&[u64])->Result<(),String>{for(index,value)in values.iter().enumerate(){projection.insert(table,&[I(id),I(ordinal(index)?),I(high(*value)),I(low(*value))])?;}Ok(())}
pub(super) fn read_handles(reader:&mut Reader<'_,'_,'_>,table:&'static str,id:i64)->Result<Vec<u64>,String>{reader.list(table,1,id,2)?.into_iter().map(|row|full_unsigned(row,3,4)).collect()}
fn reference(value:DwgEntityReferenceMode)->&'static str{match value{DwgEntityReferenceMode::ByLayer=>"by_layer",DwgEntityReferenceMode::ByBlock=>"by_block",DwgEntityReferenceMode::Continuous=>"continuous",DwgEntityReferenceMode::Explicit=>"explicit"}}
fn read_reference(value:&str)->Result<DwgEntityReferenceMode,String>{match value{"by_layer"=>Ok(DwgEntityReferenceMode::ByLayer),"by_block"=>Ok(DwgEntityReferenceMode::ByBlock),"continuous"=>Ok(DwgEntityReferenceMode::Continuous),"explicit"=>Ok(DwgEntityReferenceMode::Explicit),_=>Err("DWG entity reference mode is unknown".into())}}
fn project_common(projection:&mut Projection<'_,'_>,id:i64,v:&DwgEntityCommon)->Result<(),String>{
    let mode=match v.mode{DwgEntityMode::ExplicitOwner=>"explicit_owner",DwgEntityMode::PaperSpace=>"paper_space",DwgEntityMode::ModelSpace=>"model_space",DwgEntityMode::Reserved=>"reserved"};
    let linetype=optional_words(v.linetype_handle);let material=optional_words(v.material_handle);let shadow=optional_words(v.shadow_handle);let plot=optional_words(v.plot_style_handle);let full=optional_words(v.full_visual_style_handle);let face=optional_words(v.face_visual_style_handle);let edge=optional_words(v.edge_visual_style_handle);
    projection.insert_key("dwg_entity_common",id,&[T(mode),R(v.linetype_scale),T(reference(v.linetype)),T(reference(v.plot_style)),T(reference(v.material)),I(i64::from(v.shadow)),I(i64::from(v.invisible)),I(i64::from(v.lineweight)),I(high(v.layer_handle)),I(low(v.layer_handle)),linetype[0],linetype[1],material[0],material[1],shadow[0],shadow[1],plot[0],plot[1],full[0],full[1],face[0],face[1],edge[0],edge[1]])?;
    let color=&v.color;let kind=match color.kind{DwgEntityColorKind::ByLayer=>"by_layer",DwgEntityColorKind::ByBlock=>"by_block",DwgEntityColorKind::Index=>"index",DwgEntityColorKind::TrueColor=>"true_color"};let handle=optional_words(color.color_handle);
    projection.insert_key("dwg_entity_color",id,&[T(kind),I(i64::from(color.index)),I(i64::from(color.rgb)),color.transparency.map(|value|I(i64::from(value))).unwrap_or(N),color.name.as_deref().map(T).unwrap_or(N),color.book_name.as_deref().map(T).unwrap_or(N),handle[0],handle[1]])
}
fn read_common(reader:&mut Reader<'_,'_,'_>,id:i64)->Result<DwgEntityCommon,String>{
    let row=reader.component("dwg_entity_common",id)?;let r=reader.component("dwg_entity_color",id)?;
    let color=DwgEntityColor{kind:match r.text(1)?{"by_layer"=>DwgEntityColorKind::ByLayer,"by_block"=>DwgEntityColorKind::ByBlock,"index"=>DwgEntityColorKind::Index,"true_color"=>DwgEntityColorKind::TrueColor,_=>return Err("DWG entity color kind is unknown".into())},index:word(r,2)?,rgb:unsigned(r,3)?,transparency:optional_integer(r,4)?,name:optional_text(r,5)?,book_name:optional_text(r,6)?,color_handle:optional_unsigned(r,7,8)?};
    Ok(DwgEntityCommon{mode:match row.text(1)?{"explicit_owner"=>DwgEntityMode::ExplicitOwner,"paper_space"=>DwgEntityMode::PaperSpace,"model_space"=>DwgEntityMode::ModelSpace,"reserved"=>DwgEntityMode::Reserved,_=>return Err("DWG entity mode is unknown".into())},color,linetype_scale:real(row,2)?,linetype:read_reference(row.text(3)?)?,plot_style:read_reference(row.text(4)?)?,material:read_reference(row.text(5)?)?,shadow:byte(row,6)?,invisible:word(row,7)?,lineweight:byte(row,8)?,layer_handle:full_unsigned(row,9,10)?,linetype_handle:optional_unsigned(row,11,12)?,material_handle:optional_unsigned(row,13,14)?,shadow_handle:optional_unsigned(row,15,16)?,plot_style_handle:optional_unsigned(row,17,18)?,full_visual_style_handle:optional_unsigned(row,19,20)?,face_visual_style_handle:optional_unsigned(row,21,22)?,edge_visual_style_handle:optional_unsigned(row,23,24)?})
}
pub(super) fn reconstruct(reader:&mut Reader<'_,'_,'_>,id:i64)->Result<DwgEntityBody,String>{
    let row=reader.component("dwg_entity",id)?;let common=read_common(reader,id)?;
    match row.text(1)?{
        "line"=>{let r=reader.component("dwg_line_entity",id)?;Ok(DwgEntityBody::Line(DwgLineEntity{common,start:read_coordinates(reader,"dwg_entity_line_start_coordinate",id)?,end:read_coordinates(reader,"dwg_entity_line_end_coordinate",id)?,thickness:real(r,1)?,extrusion:read_coordinates(reader,"dwg_entity_extrusion_coordinate",id)?}))},
        "arc"=>{let r=reader.component("dwg_arc_entity",id)?;Ok(DwgEntityBody::Arc(DwgArcEntity{common,center:read_coordinates(reader,"dwg_entity_center_coordinate",id)?,radius:real(r,1)?,thickness:real(r,2)?,extrusion:read_coordinates(reader,"dwg_entity_extrusion_coordinate",id)?,start_angle:real(r,3)?,end_angle:real(r,4)?}))},
        "lwpolyline"=>{
            let r=reader.component("dwg_lwpolyline_entity",id)?;let mut vertices=Vec::new();
            for child in reader.list("dwg_lwpolyline_vertex",1,id,2)?{vertices.push(DwgLwPolylineVertex{point:read_coordinates(reader,"dwg_lwpolyline_vertex_coordinate",child.rowid)?,bulge:real(child,3)?,vertex_id:optional_integer(child,4)?,start_width:optional_real(child,5)?,end_width:optional_real(child,6)?});}
            Ok(DwgEntityBody::LwPolyline(DwgLwPolylineEntity{common,closed:boolean(r,1)?,constant_width:optional_real(r,2)?,elevation:real(r,3)?,thickness:real(r,4)?,extrusion:read_coordinates(reader,"dwg_entity_extrusion_coordinate",id)?,vertices}))
        },
        "block_begin"=>{reader.component("dwg_block_begin_entity",id)?;Ok(DwgEntityBody::BlockBegin(DwgBlockBeginEntity{common}))},
        "block_end"=>{reader.component("dwg_block_end_entity",id)?;Ok(DwgEntityBody::BlockEnd(DwgBlockEndEntity{common}))},
        "sequence_end"=>{reader.component("dwg_sequence_end_entity",id)?;Ok(DwgEntityBody::SequenceEnd(DwgSequenceEndEntity{common}))},
        "insert"=>{let r=reader.component("dwg_insert_entity",id)?;Ok(DwgEntityBody::Insert(DwgInsertEntity{common,insertion:read_coordinates(reader,"dwg_entity_insert_insertion_coordinate",id)?,scale:read_coordinates(reader,"dwg_entity_insert_scale_coordinate",id)?,rotation:real(r,1)?,extrusion:read_coordinates(reader,"dwg_entity_extrusion_coordinate",id)?,block_header_handle:full_unsigned(r,2,3)?,attribute_handles:read_handles(reader,"dwg_insert_attribute_handle",id)?,sequence_end_handle:optional_unsigned(r,4,5)?}))},
        "point"=>{let r=reader.component("dwg_point_entity",id)?;Ok(DwgEntityBody::Point(DwgPointEntity{common,point:read_coordinates(reader,"dwg_entity_point_coordinate",id)?,thickness:real(r,1)?,extrusion:read_coordinates(reader,"dwg_entity_extrusion_coordinate",id)?,x_axis_angle:real(r,2)?}))},
        "circle"=>{let r=reader.component("dwg_circle_entity",id)?;Ok(DwgEntityBody::Circle(DwgCircleEntity{common,center:read_coordinates(reader,"dwg_entity_center_coordinate",id)?,radius:real(r,1)?,thickness:real(r,2)?,extrusion:read_coordinates(reader,"dwg_entity_extrusion_coordinate",id)?}))},
        "ellipse"=>{let r=reader.component("dwg_ellipse_entity",id)?;Ok(DwgEntityBody::Ellipse(DwgEllipseEntity{common,center:read_coordinates(reader,"dwg_entity_center_coordinate",id)?,major_axis:read_coordinates(reader,"dwg_entity_ellipse_major_axis_coordinate",id)?,extrusion:read_coordinates(reader,"dwg_entity_extrusion_coordinate",id)?,axis_ratio:real(r,1)?,start_parameter:real(r,2)?,end_parameter:real(r,3)?}))},
        "text"=>{
            let r=reader.component("dwg_text_entity",id)?;let coordinates=read_coordinates(reader,"dwg_entity_text_alignment_coordinate",id)?;
            let alignment=if boolean(r,2)?{Some(coordinates)}else{if !coordinates.is_empty(){return Err("DWG absent text alignment has coordinates".into());}None};
            Ok(DwgEntityBody::Text(DwgTextEntity{common,elevation:real(r,1)?,insertion:read_coordinates(reader,"dwg_entity_text_insertion_coordinate",id)?,alignment,extrusion:read_coordinates(reader,"dwg_entity_extrusion_coordinate",id)?,thickness:real(r,3)?,oblique_angle:real(r,4)?,rotation:real(r,5)?,height:real(r,6)?,width_factor:real(r,7)?,value:r.text(8)?.into(),generation:word(r,9)?,horizontal_alignment:word(r,10)?,vertical_alignment:word(r,11)?,style_handle:full_unsigned(r,12,13)?}))
        },
        "spline"=>{let r=reader.component("dwg_spline_entity",id)?;Ok(DwgEntityBody::Spline(DwgSplineEntity{common,degree:unsigned(r,1)?,rational:boolean(r,2)?,closed:boolean(r,3)?,periodic:boolean(r,4)?,knot_tolerance:real(r,5)?,control_tolerance:real(r,6)?,knots:read_coordinates(reader,"dwg_entity_spline_knot",id)?,control_points:read_coordinates(reader,"dwg_entity_spline_control_coordinate",id)?,weights:read_coordinates(reader,"dwg_entity_spline_weight",id)?}))},
        "face3d"=>{let r=reader.component("dwg_face3d_entity",id)?;Ok(DwgEntityBody::Face3d(DwgFace3dEntity{common,corners:read_coordinates(reader,"dwg_entity_face3d_corner_coordinate",id)?,invisible_edges:word(r,1)?}))},
        "polyline3d"=>{let r=reader.component("dwg_polyline3d_entity",id)?;Ok(DwgEntityBody::Polyline3d(DwgPolyline3dEntity{common,curve_type:byte(r,1)?,flags:byte(r,2)?,vertex_handles:read_handles(reader,"dwg_polyline3d_vertex_handle",id)?,sequence_end_handle:full_unsigned(r,3,4)?}))},
        "polyface_mesh"=>{let r=reader.component("dwg_polyface_mesh_entity",id)?;Ok(DwgEntityBody::PolyfaceMesh(DwgPolyfaceMeshEntity{common,vertex_count:word(r,1)?,face_count:word(r,2)?,vertex_handles:read_handles(reader,"dwg_polyface_mesh_vertex_handle",id)?,sequence_end_handle:full_unsigned(r,3,4)?}))},
        "vertex"=>{let r=reader.component("dwg_vertex_entity",id)?;Ok(DwgEntityBody::Vertex(DwgVertexEntity{common,flags:byte(r,1)?,point:read_coordinates(reader,"dwg_entity_vertex_coordinate",id)?}))},
        "polyface_face"=>{reader.component("dwg_polyface_face_entity",id)?;Ok(DwgEntityBody::PolyfaceFace(DwgPolyfaceFaceEntity{common,indices:reader.list("dwg_polyface_face_index",1,id,2)?.into_iter().map(|row|signed_word(row,3)).collect::<Result<_,_>>()?}))},
        "dimension_linear"=>entity_dimension::reconstruct(reader,id,common).map(DwgEntityBody::DimensionLinear),"viewport"=>entity_viewport::reconstruct(reader,id,common).map(DwgEntityBody::Viewport),
        _=>Err("DWG entity body kind is unknown".into())
    }
}
